            steps_completed INTEGER,
            status TEXT DEFAULT 'running',
            error TEXT
        );
INSERT INTO runs VALUES('fc7b1cd8-7ab3-49a5-acf6-12344861e4cc','Stripe','2026-10-21T18:59:40.218557','2026-10-21T18:59:49.120288',8901,0,'success',NULL);
INSERT INTO runs VALUES('a5086065-c2b8-4983-b7b1-027a44785568','Notion','2026-10-21T18:59:49.122936','2026-10-21T19:00:02.307118',13184,0,'success',NULL);
INSERT INTO runs VALUES('d806e53b-c886-46f5-b66e-53f11eb95918','Linear','2026-10-21T19:00:02.308325','2026-10-21T19:00:11.186914',8878,0,'success',NULL);
CREATE TABLE steps (
            step_id TEXT PRIMARY KEY,
            run_id TEXT NOT NULL,
            step_name TEXT NOT NULL,
            started_at TEXT NOT NULL,
            finished_at TEXT,
            latency_ms INTEGER,
            input_text TEXT,
