        );
INSERT INTO steps VALUES('99158eaa-17fa-4a9d-bc12-49be9ec71a94','fc7b1cd8-7ab3-49a5-acf6-12344861e4cc','research_company','2026-10-21T18:59:40.223019','2026-10-21T18:59:42.832858',2609,'Company: Stripe','Stripe is a global financial‑services and SaaS platform that enables businesses of any size to accept online and mobile payments, create flexible billing models, and manage money‑movement across borders. It serves the worldwide e‑commerce and digital‑services market, processing transactions for roughly 5 million merchants and handling over $1.9 trillion in payment volume in 2025. Valued at about $159 billion, Stripe is the largest privately‑owned fintech company, with operations headquartered in the United States and Ireland. Its core value proposition is a developer‑first API and suite of integrated tools that simplify complex payment, fraud‑prevention, and financial‑infrastructure needs, allowing companies to launch and scale revenue streams quickly and securely.',3,193,'success',NULL);
INSERT INTO steps VALUES('59ee178e-c201-423b-909e-fea7546f4779','fc7b1cd8-7ab3-49a5-acf6-12344861e4cc','find_recent_news','2026-10-21T18:59:42.837437','2026-10-21T18:59:45.120438',2283,'Company: Stripe',replace('- In its 2025 annual update released on Feb 24 2026, Stripe reported that the 2025 cohort of new merchants was the largest ever, with 57 % of those businesses based outside the United States and the cohort growing roughly 50 % faster than the 2024 group.  \n- The letter also highlighted a broader international expansion and accelerated revenue growth, signaling that Stripe’s platform is scaling rapidly across new markets and verticals.  \n\nThese points together underscore Stripe’s strong growth momentum and its push to deepen global reach, rather than any new funding round or product launch.','\n',char(10)),3,149,'success',NULL);
INSERT INTO steps VALUES('b8f94b36-a3a5-4a35-bdf8-c244419f56e4','fc7b1cd8-7ab3-49a5-acf6-12344861e4cc','identify_decision_makers','2026-10-21T18:59:45.124451','2026-10-21T18:59:48.064549',2940,'Company: Stripe',replace('**1. Patrick Collison – Co‑founder & Chief Executive Officer**  \n*Focus:* Sets Stripe’s overall strategic direction, drives global expansion, and oversees product‑innovation and market‑entry initiatives across the payments platform.\n\n**2. Jeff Titterton – President, Global Sales & Partnerships**  \n*Focus:* Leads the worldwide sales organization, builds enterprise partnerships, and is responsible for revenue growth and go‑to‑market strategy for Stripe’s suite of financial‑services products.\n\n**3. Steffan Tomlinson – Chief Product Officer**  \n*Focus:* Guides product vision and roadmap, prioritizing new payment‑infrastructure features, developer experience, and the rollout of emerging fintech solutions.','\n',char(10)),3,177,'success',NULL);
INSERT INTO steps VALUES('a16fd131-d356-47bb-8947-c41520ea1138','fc7b1cd8-7ab3-49a5-acf6-12344861e4cc','write_outreach_summary','2026-10-21T18:59:48.067016','2026-10-21T18:59:49.116584',1049,'Company: Stripe',replace('Hi Jeff,\n\nCongrats on the record‑breaking 2025 merchant cohort—especially the 57 % surge outside the U.S., which underscores how Stripe’s developer‑first API is becoming the go‑to infrastructure for global e‑commerce. I’ve been mapping how enterprise partners can accelerate that cross‑border momentum by embedding localized fraud‑prevention and real‑time settlement tools directly into Stripe’s existing suite. Would love to explore a quick call on how we could help turn that 50 % growth acceleration into even faster revenue pipelines for your international sales teams.','\n',char(10)),3,143,'success',NULL);
INSERT INTO steps VALUES('83be42e4-2ea2-4771-af6d-666be67b91a2','a5086065-c2b8-4983-b7b1-027a44785568','research_company','2026-10-21T18:59:49.132303','2026-10-21T18:59:53.517386',4385,'Company: Notion','Notion is an all‑in‑one productivity platform that combines note‑taking, knowledge‑base, document, and project‑management tools into a single collaborative workspace, now enhanced with Notion AI assistants. Its primary market is knowledge workers and small‑to‑mid‑size technology teams (typically 5‑100 employees) that need a flexible, cross‑functional solution for documentation, planning, and task tracking. The service is used by over 100 million registered users worldwide and operates from its San Francisco headquarters with additional offices around the globe. Notion’s value proposition lies in unifying disparate productivity apps into one customizable, cloud‑based environment that streamlines collaboration while leveraging AI to automate content creation and organization.',3,196,'success',NULL);
INSERT INTO steps VALUES('8abbdaf7-0b3b-4a71-903e-8c00b8b9084a','a5086065-c2b8-4983-b7b1-027a44785568','find_recent_news','2026-10-21T18:59:53.521716','2026-10-21T18:59:57.151900',3630,'Company: Notion',replace('- In early 2025 Notion rolled out a redesigned AI‑model picker that gives users instant access to the latest frontier models—including Opus 5, GPT‑5.6 Sol and Kimi K3—letting them choose the best balance of speed, intelligence and cost for each task.  \n- At the “Make with Notion” conference (Oct 2024) the company announced its biggest bundle of product releases ever, adding new low‑code building blocks, collaborative templates and sharing tools that tighten Notion’s position as an all‑in‑one work platform.  \n- Shortly after, Notion disclosed that it has surpassed **$500 million in annual recurring revenue**, a growth milestone that coincided with the launch of a customizable AI agent capable of generating documents and pulling data from multiple sources via OpenAI‑powered models.','\n',char(10)),3,197,'success',NULL);
INSERT INTO steps VALUES('a3a88b09-d028-412b-b34a-26e57c2d40f5','a5086065-c2b8-4983-b7b1-027a44785568','identify_decision_makers','2026-10-21T18:59:57.156699','2026-10-21T19:00:01.301106',4144,'Company: Notion',replace('**1. Ivan Zhao – Co‑Founder & Chief Executive Officer**  \n*Focus:* Sets overall vision and product strategy for Notion, driving growth, fundraising, and the company’s long‑term roadmap.\n\n**2. Akshay Kothari – Co‑Founder & President (Chief Operating Officer)**  \n*Focus:* Oversees day‑to‑day operations, scaling the organization, and aligning cross‑functional teams around execution and go‑to‑market initiatives.\n\n**3. Stephen Chandler – Chief Financial Officer**  \n*Focus:* Manages financial planning, investor relations, and capital allocation to support Notion’s rapid expansion and profitability goals.','\n',char(10)),3,151,'success',NULL);
INSERT INTO steps VALUES('5657057f-4b08-4235-8828-33d61bd6a0bf','a5086065-c2b8-4983-b7b1-027a44785568','write_outreach_summary','2026-10-21T19:00:01.304987','2026-10-21T19:00:02.304149',999,'Company: Notion',replace('Hi Akshay,\n\nCongrats on hitting the $500 M ARR milestone and unveiling the customizable AI agent that can pull data across sources—exactly the kind of cross‑functional automation that’s reshaping how tech teams work. I was especially impressed by the new AI‑model picker you launched in early 2025; giving teams instant access to Opus 5, GPT‑5.6 Sol, and Kimi K3 feels like a game‑changer for balancing speed, intelligence, and cost.','\n',char(10)),3,108,'success',NULL);
INSERT INTO steps VALUES('f5e24e60-a404-458b-950e-1623ce4cd76f','d806e53b-c886-46f5-b66e-53f11eb95918','research_company','2026-10-21T19:00:02.312298','2026-10-21T19:00:06.320282',4007,'Company: Linear','Linear is a SaaS platform that streamlines issue tracking, project planning, and product road‑mapping for software development teams, offering a fast, minimalist UI and deep integrations with tools like GitHub, GitLab, Slack, and Figma. It targets tech‑focused companies—from early‑stage startups to mid‑market enterprises—that need a high‑performance alternative to traditional, heavyweight project‑management suites. With roughly 150‑200 employees and over $100 million in venture funding (Series B valuation in the high‑hundreds of millions), Linear has quickly become a go‑to solution for modern engineering workflows. Its core value proposition is delivering speed and simplicity without sacrificing the rich feature set required for coordinated software delivery.',3,192,'success',NULL);
INSERT INTO steps VALUES('6ac57087-78d3-441a-8e69-151d90d497ce','d806e53b-c886-46f5-b66e-53f11eb95918','find_recent_news','2026-10-21T19:00:06.323628','2026-10-21T19:00:08.094227',1770,'Company: Linear','Linear announced a $82 million Series C round on June 10‑11 2025, pushing its valuation past the $1 billion unicorn threshold and underscoring its status as a high‑growth, profitable enterprise‑software company. The funding round highlighted that more than 15,000 organizations—including marquee names such as OpenAI, CashApp, Ramp, Scale AI, and Boom—have adopted Linear to replace legacy product‑development tools. This influx of capital is being used to expand its product suite for product teams and accelerate further market penetration.',3,135,'success',NULL);
INSERT INTO steps VALUES('9731d0d2-147c-4a39-bc94-c620694405bf','d806e53b-c886-46f5-b66e-53f11eb95918','identify_decision_makers','2026-10-21T19:00:08.098548','2026-10-21T19:00:10.086268',1987,'Company: Linear',replace('**1. Karri Saarinen – Chief Executive Officer (CEO)**  \n*Focus:* As the founder‑CEO, Karri drives Linear’s overall vision, growth strategy, and go‑to‑market positioning, steering the company toward becoming the leading workflow tool for software teams.\n\n**2. Cristina Cordova – Chief Technology Officer (CTO)**  \n*Focus:* Cristina oversees the product engineering roadmap, ensuring the platform’s performance, scalability, and integration capabilities stay ahead of developer needs.\n\n**3. (Optional) [Name not listed in the snippets – e.g., Head of Product]**  \n*If a third decision‑maker is needed, the executive team page also lists a Head of Product (often titled “VP of Product” or “Chief Product Officer”) who is responsible for defining feature priorities, user experience, and aligning product development with market demand.  \n\n*Note:* The executive‑team listings on Linear’s website and the official board chart highlight Karri Saarinen and Cristina Cordova as the primary decision‑makers for strategy and technology, respectively.','\n',char(10)),3,260,'success',NULL);
INSERT INTO steps VALUES('212eaaab-ccb1-4863-87dd-1b3f7b064ada','d806e53b-c886-46f5-b66e-53f11eb95918','write_outreach_summary','2026-10-21T19:00:10.090269','2026-10-21T19:00:11.184247',1093,'Company: Linear','Karri, congratulations on hitting the $1 billion unicorn milestone with the $82 M Series C—seeing OpenAI and Scale AI join the roster really underscores how Linear’s speed‑first UI is reshaping modern engineering workflows. I noticed Cristina’s push to deepen integrations, especially with GitHub and Figma, and wondered how you’re planning to keep that frictionless experience while scaling to the next wave of product‑team users.',3,107,'success',NULL);
CREATE TABLE evals (
            eval_id TEXT PRIMARY KEY,
            step_id TEXT NOT NULL,
            run_id TEXT NOT NULL,
            step_name TEXT NOT NULL,
            score REAL,
            reasoning TEXT,
            evaluated_at TEXT NOT NULL,
            FOREIGN KEY (step_id) REFERENCES steps(step_id)
        );
